// spec: .qa/e2e/specs/post-create.md · seed: tests/seed.free.spec.ts · кейс .qa/tests/post-create/PC-07.md
import { test, expect } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { IPHONE, authFile, form, isPostCreate, openComposer, qaText, tap } from './post-helpers';

test.use({ ...IPHONE, storageState: authFile('free') });

test.describe('מסך יצירת פוסט', () => {
  test('✕ «סגירה» возвращает в ленту без публикации @iphone @prod-safe (#1ff0f4)', async ({ page }) => {
    let posts = 0;
    page.on('request', (r) => { if (isPostCreate(r)) posts++; });
    const text = qaText('close');
    try {
      await openComposer(page);
      await form(page).text.fill(text);
      await tap(page, form(page).close);
      await page.waitForURL(/\/social/);
      await expect(page.getByText('פוסטים', { exact: true })).toBeVisible();
      await expect(page.getByText(text, { exact: true })).toHaveCount(0);
      expect(posts, 'POST /rest/v1/posts').toBe(0);
    } finally {
      await saveSession(page, 'free');
    }
  });
});
